function class.getActivityUIConfigByActId(id)
  local nianMonsterCfg = ed.getDataTable("NianMonster")[id]
  local type = nianMonsterCfg.Type or "Hell"
  return class.TYPE_TO_UI[type]
end

function class.getActivityRulesByActId(id)
  local nianMonsterCfg = ed.getDataTable("NianMonster")[id]
  local type = nianMonsterCfg.Type or "Hell"
  local title, text
  if type == "Hell" then
    title = ed.hadesDefine.RULES_TITLE
    text = ed.hadesDefine.RULES_TEXT
  else
    title = class.RULES_TITLE
    text = class.RULES_TEXT
  end
  return title, text
end
